import { SUBWAY_SET_SUNDAY } from './sunday.ts';
import { SUBWAY_SET_MONDAY } from './monday.ts';
import { SUBWAY_SET_TUESDAY } from './tuesday.ts';
import { SUBWAY_SET_WEDNESDAY } from './wednesday.ts';
import { SUBWAY_SET_THURSDAY } from './thursday.ts';
import { SUBWAY_SET_FRIDAY } from './friday.ts';
import { SUBWAY_SET_SATURDAY } from './saturday.ts';
import type { SubwayDailySet } from '../subwayTrainers.ts';

export const SUBWAY_DAILY_SETS: SubwayDailySet[] = [
    SUBWAY_SET_SUNDAY,
    SUBWAY_SET_MONDAY,
    SUBWAY_SET_TUESDAY,
    SUBWAY_SET_WEDNESDAY,
    SUBWAY_SET_THURSDAY,
    SUBWAY_SET_FRIDAY,
    SUBWAY_SET_SATURDAY,
];

Object.freeze(SUBWAY_DAILY_SETS);
for (const set of SUBWAY_DAILY_SETS) {
    Object.freeze(set);
    Object.freeze(set.trainers);
    for (const trainer of set.trainers) {
        Object.freeze(trainer);
        Object.freeze(trainer.team);
    }
}
