/**
 * @file zoneMasterySpecies.ts
 * Zone pool helpers for mastery progression (no Creature / questSystem deps).
 * Shared by zoneSystem.ts and src/ui/zoneDisplay.ts (strict-index-ui isolation).
 */

import { coerceStr } from './src/lib/coerceStr.ts';
import { resolveCanonicalSpeciesName } from './src/lib/rosterSpeciesAliases.ts';
import { ZONES as _ZONES, ZONE_POKEMON as _ZONE_POKEMON } from './constants/balance/zonesAndPacing.ts';
import type { GameRuntime, ZonePokemonEntry, ZonePokemonPool } from './src/types/game.js';

const ZONE_POKEMON = _ZONE_POKEMON as Record<number, unknown>;
const ZONES = _ZONES as Record<number, { regionId?: string }>;

function _zoneMasteryIncludesAllSpawnChannels(zoneId: number): boolean {
    const zone = ZONES[zoneId];
    const regionId = zone?.regionId;
    if (regionId === 'johto' || regionId === 'hoenn' || regionId === 'sinnoh' || regionId === 'unova' || regionId === 'kalos' || regionId === 'alola' || regionId === 'galar' || regionId === 'paldea') return true;
    const z = Number(zoneId);
    return (z >= 101 && z <= 199) || (z >= 201 && z <= 299) || (z >= 401 && z <= 445) || (z >= 501 && z <= 550) || (z >= 601 && z <= 650);
}

function _allChannelMasterySpeciesFromStructuredPool(zoneData: unknown, zoneId: number): string[] {
    const zd = zoneData as ZonePokemonPool;
    let all: ZonePokemonEntry[] = [];
    if (zd.land) {
        all = all.concat(Array.isArray(zd.land) ? zd.land : [zd.land]);
    }
    all = all.concat(_getZoneWaterEntries(zoneData, zoneId) as ZonePokemonEntry[]);
    all = all.concat(_getZoneFishingEntries(zoneData, zoneId) as ZonePokemonEntry[]);
    return [...new Set(all
        .filter((entry) => _zoneEntryCountsTowardZoneMastery(entry))
        .map((entry) => _zoneEntryToName(entry)))];
}

export function _zoneEntryToName(entry: string | { name?: string; [key: string]: unknown }): string {
    const raw = typeof entry === 'object' && entry && entry.name != null ? coerceStr(entry.name) : coerceStr(entry);
    return resolveCanonicalSpeciesName(raw);
}

/** Entrée de pool exclue du prérequis de maîtrise zone (bonus, quête narrative, etc.). */
export function _zoneEntryCountsTowardZoneMastery(entry: string | { optionalRegionBlock?: boolean; excludeFromZoneMastery?: boolean; [key: string]: unknown }): boolean {
    if (typeof entry === 'object' && entry && entry.excludeFromZoneMastery === true) return false;
    return true;
}

