export function _getZoneWaterEntries(zoneData: unknown, zoneId: number): string[] {
    if (zoneData && typeof zoneData === 'object' && !Array.isArray(zoneData) && (zoneData as Record<string, unknown>).water) {
        const w = (zoneData as Record<string, unknown[]>).water;
        return Array.isArray(w) ? (w as string[]) : (w != null ? [String(w)] : []);
    }
    const fallback = KANTO_WATER_BY_ZONE_FALLBACK[zoneId];
    return Array.isArray(fallback) ? fallback : [];
}

export function _getZoneFishingEntries(zoneData: unknown, zoneId: number): string[] {
    if (zoneData && typeof zoneData === 'object' && !Array.isArray(zoneData) && (zoneData as Record<string, unknown>).fishing) {
        const f = (zoneData as Record<string, unknown[]>).fishing;
        return Array.isArray(f) ? (f as string[]) : (f != null ? [String(f)] : []);
    }
    const fallback = KANTO_FISHING_BY_ZONE_FALLBACK[zoneId];
    return Array.isArray(fallback) ? fallback : [];
}

/** Unique species names from a tagged flat pool (all channels), sorted. */
export function getUniqueSpeciesFromTaggedPool(pool: unknown): string[] {
    if (!Array.isArray(pool)) return [];
    const names = (pool as unknown[])
        .filter((entry) => _zoneEntryCountsTowardZoneMastery(entry as string | { excludeFromZoneMastery?: boolean; [key: string]: unknown }))
        .map((entry) => _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown }))
        .filter(Boolean);
    return [...new Set(names)].sort((a, b) => a.localeCompare(b));
}

/** Unique species names in a zone pool (all channels), sorted. Used for census quests. */
export function getUniqueSpeciesInZonePool(zoneId: number): string[] {
    const zoneData = ZONE_POKEMON[zoneId] as unknown;
    if (!zoneData) return [];

    if (Array.isArray(zoneData)) {
        return getUniqueSpeciesFromTaggedPool(zoneData);
    }

    if (typeof zoneData === 'object') {
        const zd = zoneData as ZonePokemonPool;
        let all: string[] = [];
        if (zd.land) {
            all = all.concat(Array.isArray(zd.land) ? zd.land.map((e) => _zoneEntryToName(e)) : [_zoneEntryToName(zd.land)]);
        }
        all = all.concat(_getZoneWaterEntries(zoneData, zoneId).map((e) => _zoneEntryToName(e)));
        all = all.concat(_getZoneFishingEntries(zoneData, zoneId).map((e) => _zoneEntryToName(e)));
        return [...new Set(all.filter(Boolean))].sort((a, b) => a.localeCompare(b));
    }

    return [];
}

/**
 * Pokemon used for progression mastery checks.
 * Johto/Hoenn/Sinnoh/Unova/Kalos: all spawn channels (land + surf + fishing) count toward mastery.
 * Other regions: excludes optional key-item pools (Surf/Fishing) when a land pool exists.
 * When no land pool exists (aquatic-only routes), water + fishing entries count.
 */
export function getProgressionMasteryPokemonInZoneLogic(_game: GameRuntime, zoneId: number): string[] {
    const zoneData = ZONE_POKEMON[zoneId] as unknown;
    if (!zoneData) return [];

    if (_zoneMasteryIncludesAllSpawnChannels(zoneId)) {
        if (Array.isArray(zoneData)) {
            return getUniqueSpeciesFromTaggedPool(zoneData);
        }
        if (typeof zoneData === 'object') {
            return _allChannelMasterySpeciesFromStructuredPool(zoneData, zoneId);
        }
        return [];
    }

    if (Array.isArray(zoneData)) {
        const list = zoneData as unknown[];
        const usesChannelTags = list.some((entry) => {
            return typeof entry === 'object' && entry != null
                && ((entry as { channel?: string }).channel === 'land'
                    || (entry as { channel?: string }).channel === 'water'
                    || (entry as { channel?: string }).channel === 'fishing');
        });
        let masteryEntries: unknown[];
        if (usesChannelTags) {
            const landEntries = list.filter((entry) => {
                if (typeof entry !== 'object' || !entry) return false;
                const ch = (entry as { channel?: string }).channel;
                return !ch || ch === 'land';
            });
            masteryEntries = landEntries.length
                ? landEntries
                : list.filter((entry) => {
                    if (typeof entry !== 'object' || !entry) return false;
                    const ch = (entry as { channel?: string }).channel;
                    return ch === 'water' || ch === 'fishing';
                });
        } else {
            masteryEntries = list;
        }
        return [...new Set(masteryEntries
            .filter((entry) => _zoneEntryCountsTowardZoneMastery(entry as string | { optionalRegionBlock?: boolean; [key: string]: unknown }))
            .map((entry) => _zoneEntryToName(entry as string | { name?: string; [key: string]: unknown })))];
    }

    if (zoneData && typeof zoneData === 'object') {
        const zd = zoneData as ZonePokemonPool;
        const landEntries = zd.land
            ? (Array.isArray(zd.land) ? zd.land : [zd.land])
            : [];
        if (landEntries.length) {
            return [...new Set(landEntries
                .filter((entry) => _zoneEntryCountsTowardZoneMastery(entry))
                .map((entry) => _zoneEntryToName(entry)))];
        }

        const waterEntries = _getZoneWaterEntries(zoneData, zoneId);
        if (waterEntries.length) {
            return [...new Set(waterEntries
                .filter((entry) => _zoneEntryCountsTowardZoneMastery(entry))
                .map((entry) => _zoneEntryToName(entry)))];
        }

        const fishingEntries = _getZoneFishingEntries(zoneData, zoneId);
        if (fishingEntries.length) {
            return [...new Set(fishingEntries
                .filter((entry) => _zoneEntryCountsTowardZoneMastery(entry))
                .map((entry) => _zoneEntryToName(entry)))];
        }
    }

    return [];
}
