/**
 * Header skin unlock conditions (achievements, story quests, stats, Pokédex).
 */
import { ACHIEVEMENTS } from '../../constants/questsAchievements.ts';
import { STORY_QUESTS } from '../../constants/storyQuests.ts';
import {
    NON_DEX_SPRITE_PLACEHOLDERS,
    POKEMON_SPRITE_IDS,
} from '../../constants/balance/dexAndCapture.js';
import type { GameStats } from '../types/game.js';

export const HEADER_SKIN_ALWAYS_UNLOCKED_ID = 'classic_lab';

export type HeaderSkinUnlockCondition =
    | { type: 'achievement'; id: string }
    | { type: 'storyQuest'; id: string }
    | { type: 'stat'; key: string; min: number }
    | { type: 'pokedexUnique'; min: number };

export interface HeaderSkinDefLike {
    id: string;
    unlockAchievementId?: string | null;
    unlockCondition?: HeaderSkinUnlockCondition | null;
}

export interface HeaderSkinGameContext {
    achievementsCompleted?: Record<string, unknown>;
    completedStoryQuests?: string[];
    stats?: Partial<GameStats>;
    pokedex?: Record<string, { discovered?: boolean; name?: string } | null | undefined>;
}

export interface HeaderSkinUnlockLabelContext extends HeaderSkinGameContext {
    t?: (key: string, params?: Record<string, string | number>) => string;
    getLocalizedAchievementData?: (
        id: string,
        def: Record<string, unknown> | null
    ) => { title?: string; desc?: string };
}

function isAlwaysUnlockedSkin(skin: HeaderSkinDefLike): boolean {
    return skin.id === HEADER_SKIN_ALWAYS_UNLOCKED_ID;
}

/** Resolves the active unlock condition (legacy achievement id or explicit condition). */
export function resolveSkinUnlockCondition(skin: HeaderSkinDefLike): HeaderSkinUnlockCondition | null {
    if (isAlwaysUnlockedSkin(skin)) return null;
    const raw = skin.unlockCondition;
    if (raw && typeof raw === 'object' && typeof raw.type === 'string') {
        return raw as HeaderSkinUnlockCondition;
    }
    const achId = skin.unlockAchievementId;
    if (typeof achId === 'string' && achId.length > 0) {
        return { type: 'achievement', id: achId };
    }
    return null;
}

/** Unique species discovered in the Pokédex (same logic as Game._computePokedexCompletion). */
export function countPokedexUniqueDiscovered(
    pokedex: HeaderSkinGameContext['pokedex']
): number {
    if (!pokedex || typeof pokedex !== 'object') return 0;
    const seen = new Set<string>();
    for (const entry of Object.values(pokedex)) {
        if (!entry) continue;
        const name = entry.name || '';
        if (!name) continue;
        if (entry.discovered) seen.add(name);
    }
    return seen.size;
}

/** Species names in the national dex from #1 through maxNationalDex (inclusive). */
export function getNationalDexSpeciesNamesUpTo(maxNationalDex: number): string[] {
    if (!POKEMON_SPRITE_IDS || typeof POKEMON_SPRITE_IDS !== 'object') return [];
    const cap = Math.max(0, Math.floor(Number(maxNationalDex) || 0));
    if (cap < 1) return [];
    const rows = Object.entries(POKEMON_SPRITE_IDS).map(function (e) {
        return { name: e[0], id: Number(e[1]) };
    }).filter(function (r) {
        return Number.isFinite(r.id)
            && r.id >= 1
            && r.id <= cap
            && !NON_DEX_SPRITE_PLACEHOLDERS.has(r.name);
    });
    rows.sort(function (a, b) {
        if (a.id !== b.id) return a.id - b.id;
        return String(a.name).localeCompare(String(b.name));
    });
    const byId = new Map<number, string>();
    for (const row of rows) {
        if (!byId.has(row.id)) byId.set(row.id, row.name);
    }
    return Array.from(byId.entries())
        .sort(function (a, b) { return a[0] - b[0]; })
        .map(function (e) { return e[1]; });
}

/** Unique discovered species limited to national dex #1..maxNationalDex. */
export function countPokedexUniqueDiscoveredUpTo(
    pokedex: HeaderSkinGameContext['pokedex'],
    maxNationalDex: number
): number {
    const allowed = new Set(getNationalDexSpeciesNamesUpTo(maxNationalDex));
    if (allowed.size === 0) return 0;
    if (!pokedex || typeof pokedex !== 'object') return 0;
    const seen = new Set<string>();
    for (const entry of Object.values(pokedex)) {
        if (!entry) continue;
        const name = entry.name || '';
        if (!name || !allowed.has(name)) continue;
        if (entry.discovered) seen.add(name);
    }
    return seen.size;
}

export function isHeaderSkinUnlocked(game: HeaderSkinGameContext, skin: HeaderSkinDefLike): boolean {
    if (isAlwaysUnlockedSkin(skin)) return true;
    const cond = resolveSkinUnlockCondition(skin);
    if (!cond) return false;
    switch (cond.type) {
        case 'achievement':
            return !!(game.achievementsCompleted && game.achievementsCompleted[cond.id]);
        case 'storyQuest':
            return Array.isArray(game.completedStoryQuests) && game.completedStoryQuests.includes(cond.id);
        case 'stat': {
            const stats = game.stats;
            const current = stats ? Number((stats as Record<string, number>)[cond.key]) || 0 : 0;
            return current >= cond.min;
        }
        case 'pokedexUnique':
            return countPokedexUniqueDiscovered(game.pokedex) >= cond.min;
        default:
            return false;
    }
}

function storyQuestTitle(storyId: string): string {
    const quests = STORY_QUESTS as Record<string, { title?: string; id?: string }>;
    for (const def of Object.values(quests)) {
        if (!def) continue;
        if (def.id === storyId && typeof def.title === 'string' && def.title) {
            return def.title;
        }
    }
    const shortKey = storyId.replace(/^story_/, '');
    const byKey = quests[shortKey];
    if (byKey && typeof byKey.title === 'string' && byKey.title) return byKey.title;
    return storyId;
}

function statLabelKey(statKey: string): string {
    return `menu.statLabel.${statKey}`;
}

export function getHeaderSkinUnlockLabel(
    ctx: HeaderSkinUnlockLabelContext,
    skin: HeaderSkinDefLike
): string {
    const t = ctx.t ?? ((key: string, vars?: Record<string, string | number>) => {
        let text = key;
        if (vars) {
            for (const [k, v] of Object.entries(vars)) {
                text = text.replace(`{${k}}`, String(v));
            }
        }
        return text;
    });
    if (isAlwaysUnlockedSkin(skin)) {
        return t('menu.unlockDefault');
    }
    const cond = resolveSkinUnlockCondition(skin);
    if (!cond) return '';

    switch (cond.type) {
        case 'achievement': {
            const achDef = (ACHIEVEMENTS as Record<string, Record<string, unknown>>)[cond.id] ?? null;
            const localized = ctx.getLocalizedAchievementData
                ? ctx.getLocalizedAchievementData(cond.id, achDef)
                : null;
            const title = localized?.title ?? (typeof achDef?.title === 'string' ? achDef.title : cond.id);
            return t('menu.unlockAchievement', { value: title });
        }
        case 'storyQuest': {
            const title = storyQuestTitle(cond.id);
            return t('menu.unlockStoryQuest', { value: title });
        }
        case 'stat': {
            const statName = t(statLabelKey(cond.key));
            return t('menu.unlockStat', { min: cond.min, stat: statName });
        }
        case 'pokedexUnique':
            return t('menu.unlockPokedex', { min: cond.min });
        default:
            return '';
    }
}

/** Sanitizes persisted unlock ids (dedupe, drop unknown skins, ensure default). */
export function pruneInvalidUnlockedHeaderSkins(
    game: HeaderSkinGameContext & {
        unlockedHeaderSkins?: string[];
        selectedHeaderSkin?: string;
    },
    skins: Record<string, HeaderSkinDefLike>
): boolean {
    if (!Array.isArray(game.unlockedHeaderSkins)) return false;
    const before = game.unlockedHeaderSkins.length;
    const defaultId = HEADER_SKIN_ALWAYS_UNLOCKED_ID;
    game.unlockedHeaderSkins = game.unlockedHeaderSkins.filter((skinId, index, arr) => {
        if (arr.indexOf(skinId) !== index) return false;
        return !!skins[skinId];
    });
    if (!game.unlockedHeaderSkins.includes(defaultId)) {
        game.unlockedHeaderSkins.push(defaultId);
    }
    return game.unlockedHeaderSkins.length !== before;
}

/** Skin ids whose unlock condition is the given story quest. */
export function headerSkinIdsForStoryQuest(
    skins: Record<string, HeaderSkinDefLike>,
    storyQuestId: string
): string[] {
    const ids: string[] = [];
    for (const [skinId, def] of Object.entries(skins)) {
        if (!def) continue;
        const cond = resolveSkinUnlockCondition(def);
        if (cond?.type === 'storyQuest' && cond.id === storyQuestId) {
            ids.push(skinId);
        }
    }
    return ids;
}
