const GALAR_WILD_AREA_ZONE_IDS = [711, 740] as const;

function getGalarWildAreaCensusSpecies(): string[] {
    const names = new Set<string>();
    for (const zoneId of GALAR_WILD_AREA_ZONE_IDS) {
        for (const entry of GALAR_ZONE_POKEMON[zoneId] ?? []) {
            if (entry.excludeFromZoneMastery) continue;
            names.add(entry.name);
        }
    }
    return [...names].sort((a, b) => a.localeCompare(b));
}

const GALAR_WILD_AREA_CENSUS_SPECIES = getGalarWildAreaCensusSpecies();

