const GALAR_CHAMPION_CUP_REQUIRED_WAGON = 20;

const SINNOH_BATTLE_ZONE_IDS = [363, 364, 365, 366, 367, 368, 369, 370] as const;

function getSinnohBattleZoneCensusSpecies(): string[] {
    const names = new Set<string>();
    for (const zoneId of SINNOH_BATTLE_ZONE_IDS) {
        for (const entry of SINNOH_ZONE_POKEMON[zoneId] ?? []) {
            if (entry.channel === 'water' || entry.channel === 'fishing') continue;
            if (entry.excludeFromZoneMastery) continue;
            names.add(entry.name);
        }
    }
    return [...names].sort((a, b) => a.localeCompare(b));
}

