/** Unova post-League story keys strictly between Elite Four and Penta Champion. */
export const STORY_QUEST_UNOVA_POST_LEAGUE_ORDER_KEYS = (
    _UNOVA_ELITE_FOUR_ORDER_IDX >= 0 && _UNOVA_PENTA_ORDER_IDX > _UNOVA_ELITE_FOUR_ORDER_IDX
        ? STORY_QUEST_ORDER.slice(_UNOVA_ELITE_FOUR_ORDER_IDX + 1, _UNOVA_PENTA_ORDER_IDX)
        : []
) as readonly (typeof STORY_QUEST_ORDER)[number][];

const STORY_QUEST_UNOVA_POST_LEAGUE_ORDER_KEY_SET = new Set<string>(
    STORY_QUEST_UNOVA_POST_LEAGUE_ORDER_KEYS,
);

export function isUnovaPostLeagueStoryOrderKey(key: string): boolean {
    return STORY_QUEST_UNOVA_POST_LEAGUE_ORDER_KEY_SET.has(key);
}

