const KANTO_ARENA_ORDER_KEYS = new Set([
    'arena_first',
    'arena_second',
    'arena_third',
    'arena_fourth',
    'arena_five',
    'arena_six',
    'arena_seven',
    'arena_eight',
]);

/** Story-order keys for gym / league quests (not side quests between gyms). */
export function isArenaStoryOrderKey(key: string): boolean {
    if (KANTO_ARENA_ORDER_KEYS.has(key)) return true;
    if (key === 'elite_four' || key === 'johto_dual_gym') return true;
    if (key.endsWith('_elite_four')) return true;
    return /_arena_\d+$/.test(key);
}

/** Previous gym/league key in STORY_QUEST_ORDER, or null for arena_first / unknown. */
export function getPreviousArenaStoryOrderKey(key: string): string | null {
    if (!isArenaStoryOrderKey(key) || key === 'arena_first') return null;
    const idx = STORY_QUEST_ORDER.indexOf(key);
    if (idx <= 0) return null;
    for (let i = idx - 1; i >= 0; i--) {
        const prev = STORY_QUEST_ORDER[i];
        if (prev !== undefined && isArenaStoryOrderKey(prev)) return prev;
    }
    return null;
}

/** Linear (non-arena) story keys strictly between two arena/league keys in STORY_QUEST_ORDER. */
export function getLinearStoryOrderKeysBetween(prevArenaKey: string, arenaKey: string): string[] {
    const prevIdx = STORY_QUEST_ORDER.indexOf(prevArenaKey);
    const arenaIdx = STORY_QUEST_ORDER.indexOf(arenaKey);
    if (prevIdx < 0 || arenaIdx < 0 || arenaIdx <= prevIdx) return [];
    return STORY_QUEST_ORDER.slice(prevIdx + 1, arenaIdx).filter(
        (k) => !isArenaStoryOrderKey(k)
            && !isStoryQuestOptionalLegendaryOrderKey(k)
            && !k.startsWith('paldea_course_'),
    );
}

