/**
 * Battle Subway — trainer roster per wagon battle (1–7).
 * Daily rotation: 7 themed sets (Sunday = original Unova mix).
 * Scaling handled in subwaySystem.
 */

export interface SubwayTrainerPokemon {
    name: string;
    levelOffset?: number;
    /** Primary type override (e.g. Eelektross). */
    type?: string;
    /** Fixed moveset (French move names, same as arena trainers). */
    moves?: string[];
    /** passiveTalent key (e.g. 'adrenaline', 'muraille'). */
    talent?: string;
    /** HELD_ITEMS key (e.g. 'life_orb', 'focus_sash'). */
    heldItem?: string;
    /** Rarity for generic ultimate tier; defaults to rare. */
    rarity?: 'rare' | 'epic';
}

export interface SubwayTrainerDef {
    id: string;
    name: { fr: string; en: string };
    spriteKey: string;
    type: string;
    team: SubwayTrainerPokemon[];
    /** Historique : marquait les dresseurs 5–7 ; les ultimes ennemis suivent isTrainerBattle en combat. */
    useUltimates?: boolean;
    /** Species-level moveset fallback (arena pattern). */
    fixedMovesets?: Record<string, string[]>;
}

export interface SubwayDailySet {
    id: string;
    dayIndex: number;
    themeType: string;
    label: { fr: string; en: string };
    trainers: SubwayTrainerDef[];
}

export const SUBWAY_BATTLES_PER_WAGON = 7;

export { SUBWAY_DAILY_SETS } from './subwayDailySets/index.ts';

/** @deprecated Use getSubwayTrainersForDay() — Sunday set only for legacy imports. */
export { SUBWAY_SET_SUNDAY } from './subwayDailySets/sunday.ts';

import { SUBWAY_SET_SUNDAY } from './subwayDailySets/sunday.ts';

/** @deprecated Use SUBWAY_DAILY_SETS / getSubwayTrainersForDay() */
export const SUBWAY_TRAINERS: SubwayTrainerDef[] = SUBWAY_SET_SUNDAY.trainers;

Object.freeze(SUBWAY_TRAINERS);
